{{ (() => {
  const input = $input.item.json ?? {};
  const body = input.body ?? input;
  const e = Array.isArray(body.alerts) && body.alerts.length
    ? { ...body, ...body.alerts[0] }
    : body;

  const str = (v, fallback = "") => {
    if (v === undefined || v === null || v === "") return fallback;
    if (typeof v === "object") return JSON.stringify(v);
    return String(v);
  };

  const safe = (v, max = 1024) =>
    str(v)
      .replace(/@/g, "@\u200b")
      .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, "")
      .slice(0, max);

  const present = v =>
    v !== undefined && v !== null && v !== "";

  const value = (...values) =>
    values.find(present);

  const rawTitle = str(value(
    e.event_definition,
    e.event_definition_title,
    e.rule,
    e.title,
    body.event_definition,
    body.rule
  ));

  const rawSource = str(value(e.source, e.kind, body.kind)).toLowerCase();
  const ruleId = str(value(e.rule_id, e.wazuh_rule_id, e.rule?.id));
  const eventKey = str(value(e.event_key, e.group_key, e.key, body.event_key));

  const lowerTitle = rawTitle.toLowerCase();

  const ip = value(e.src_ip, e.srcip, e.ip, e.source_ip);
  const username = value(e.username, e.user, e.account);
  const agent = value(e.agent?.name, e.agent, e.agent_name);
  const file = value(e.file, e.path, e.syscheck?.path);

  const count = value(e.fail_count, e.count, e.login_failures);
  const packetCount = value(e.packet_count, e.packets);
  const synCount = value(e.tcp_syn_count, e.syn_count);
  const rstCount = value(e.tcp_rst_count, e.rst_count);
  const portCount = value(e.unique_dst_ports, e.port_count);
  const dstIpCount = value(e.unique_dst_ips);
  const samplePorts = value(e.sample_dst_ports);

  const reason = str(value(
    e.reason, e.description, e.text, e.message, e.title
  ));

  const decision = str(value(
    e.action, e.decision, body.decision, "alert"
  )).toLowerCase();

  const numericLevel = Number(value(e.rule_level, e.wazuh_rule_level));

  const ids = {
    "100211": ["브루트포스", "High"],
    "100220": ["웹셸 의심", "Critical"],
    "100221": ["웹 파일 위변조", "Medium"],
    "100222": ["실행형 파일 삭제", "High"],
    "100230": ["보안·감사 로그 변경", "High"],
    "100231": ["보안 설정 파일 변경", "High"],
    "100232": ["sudo 특권 명령 실행", "Medium"],
    "100233": ["사용자·그룹 변경", "High"],
    "100234": ["root SSH 로그인", "High"],
    "100235": ["비인가 SSH 접근", "High"],
    "100236": ["Flask·k3s 설정 변경", "High"],
    "100237": ["Flask·k3s 배포 파일 삭제", "High"]
  };

  let type = "general";
  let detail = "";
  let defaultSeverity = "Medium";

  const has = pattern => pattern.test(lowerTitle + " " + rawSource);

  if (ruleId && (ids[ruleId] || rawSource === "wazuh")) {
    type = "wazuh";
    detail = ids[ruleId]?.[0] ?? "Wazuh 호스트 보안";
    defaultSeverity = ids[ruleId]?.[1] ?? "Medium";
  } else if (
    has(/ed-wz|linux 호스트 보안|wazuh/) ||
    rawSource === "wazuh"
  ) {
    type = "wazuh";
    detail = "Wazuh 호스트 보안";
  } else if (
    has(/ed-k09|packet-traffic|패킷 트래픽/)
  ) {
    type = "packet";
    detail = has(/k09-01|다중 포트/)
      ? "다중 포트 접근"
      : has(/k09-02|tcp syn|syn 급증/)
        ? "TCP SYN 급증"
        : has(/k09-03|패킷 과다/)
          ? "IP별 패킷 과다"
          : "패킷 트래픽 분석";
  } else if (has(/ed-ex-01|독립 포트 스캔/)) {
    type = "network"; detail = "포트 스캔";
  } else if (has(/ed-ex-02|syn flood/)) {
    type = "network"; detail = "SYN Flood 의심";
    defaultSeverity = "High";
  } else if (has(/ed-ex-03|low.and.slow/)) {
    type = "authentication"; detail = "저속 로그인 시도";
  } else if (has(/ed-ex-04|심야 로그인/)) {
    type = "authentication"; detail = "심야 로그인 성공";
  } else if (has(/ed-ex-05|sql injection/)) {
    type = "web"; detail = "SQL Injection 의심";
    defaultSeverity = "High";
  } else if (has(/ed-ex-06|내부 비인가 접근/)) {
    type = "network"; detail = "내부 비인가 접근";
    defaultSeverity = "High";
  } else if (has(/ed-ex-07|로그 변조/)) {
    type = "host"; detail = "로그 변조·삭제";
    defaultSeverity = "High";
  } else if (has(/ed-ex-08|nikto/)) {
    type = "web"; detail = "Nikto 스캐너";
  } else if (
    has(/ed-01|privilege.guard|priv.unauthorized|rbac|관리자 권한/) ||
    rawSource === "privilege-guard"
  ) {
    type = "privilege"; detail = "관리자 권한 감사";
    defaultSeverity = "High";
  } else if (
    has(/ed-04|ip.guard|동일 ip 브루트포스/) ||
    rawSource === "ip-guard"
  ) {
    type = "ip"; detail = "IP 브루트포스";
    defaultSeverity = "High";
  } else if (
    has(/ed-05|복합공격|다중 공격 상관/) ||
    ["correlation", "spray", "aggregation"].includes(rawSource)
  ) {
    type = "correlation"; detail = "복합공격 상관분석";
    defaultSeverity = "High";
  } else if (
    has(/ed-06|incident|인시던트/) || present(e.hours)
  ) {
    type = "incident"; detail = "인시던트 승격";
    defaultSeverity = "High";
  } else if (
    has(/ed-08|login.guard|계정잠금|계정 브루트포스/) ||
    rawSource === "login-guard"
  ) {
    type = "login"; detail = "계정 브루트포스";
    defaultSeverity = "High";
  } else if (has(/ed-09|web-scan|웹스캐너|404 폭주/)) {
    type = "web"; detail = "웹스캐너 404 폭주";
    defaultSeverity = "High";
  } else if (rawSource === "scenario-alert") {
    type = "scenario"; detail = "공방전 추가 탐지";
  }

  const category = {
    privilege: ["🔐 권한 보안", 0xED4245],
    ip: ["🚫 IP 브루트포스", 0xED4245],
    login: ["🔒 계정 보안", 0xFEE75C],
    correlation: ["🚨 복합 보안 위협", 0xED4245],
    incident: ["📋 보안 인시던트", 0xF47B20],
    wazuh: ["🛡️ Wazuh 호스트 보안", 0x5865F2],
    packet: ["📡 패킷 트래픽 분석", 0x3498DB],
    network: ["🌐 네트워크 보안", 0xF47B20],
    web: ["🕸️ 웹 애플리케이션 보안", 0xFEE75C],
    authentication: ["🔑 인증 이상 탐지", 0xFEE75C],
    host: ["🖥️ 호스트 보안", 0xED4245],
    scenario: ["⚠️ 공방전 보안 탐지", 0x5865F2],
    general: ["⚠️ 보안 이벤트", 0x5865F2]
  };

  const [categoryTitle, categoryColor] = category[type];

  const rawSeverity = str(value(e.severity, body.severity));

  const priorityMap = {
    "1": "Low",
    "2": "Medium",
    "3": "High"
  };

  let severity = defaultSeverity;

  if (rawSeverity) {
    const lower = rawSeverity.toLowerCase();
    if (priorityMap[lower]) severity = priorityMap[lower];
    else if (["critical", "high", "medium", "low"].includes(lower)) {
      severity = lower[0].toUpperCase() + lower.slice(1);
    }
  } else if (type === "wazuh" && Number.isFinite(numericLevel)) {
    severity = numericLevel >= 15 ? "Critical"
      : numericLevel >= 10 ? "High"
      : numericLevel >= 7 ? "Medium"
      : "Low";
  }

  const severityColors = {
    Critical: 0x992D22,
    High: 0xED4245,
    Medium: 0xFEE75C,
    Low: 0x57F287
  };

  const actionMap = {
    block: "🚫 IP 차단 대상 판정",
    lock: "🔒 계정 잠금 대상 판정",
    revoke: "🔐 권한 회수 대상 판정",
    deny: "⛔ 접근 거부 판정",
    allow: "✅ 접근 허용 판정",
    alert: "⚠️ 보안 경보 / 검토",
    record: "📝 이벤트 기록",
    review: "🔎 추가 분석 필요"
  };

  const fields = [];

  const add = (name, v, inline = true) => {
    if (!present(v) || fields.length >= 25) return;
    const val = safe(v);
    if (val) fields.push({
      name: safe(name, 256),
      value: val,
      inline
    });
  };

  add("📡 탐지 시스템", categoryTitle);
  add("🚨 심각도", severity);
  add("⚙️ 대응 판정", actionMap[decision] ?? "🔎 추가 분석 필요", false);

  if (type !== "login" || present(ip)) {
    add("🌐 출발지 IP", ip);
  }

  add("👤 대상 계정", username);

  if (
    ["login", "ip", "authentication"].includes(type) &&
    present(count)
  ) {
    add("🔢 로그인 실패 횟수", `${count}회`);
  }

  if (type === "packet") {
    add("📦 전체 패킷 수", packetCount);
    add("🔄 TCP SYN 수", synCount);
    add("🔁 TCP RST 수", rstCount);
    add("🔌 목적지 포트 종류", portCount);
    add("🎯 목적지 IP 종류", dstIpCount);
    add("📍 목적지 포트 샘플", samplePorts, false);
  }

  if (type === "wazuh") {
    add("🆔 Wazuh Rule ID", ruleId);
    add("🖥️ Wazuh Agent", agent);
    add("📁 대상 파일", file, false);
    add("📈 Wazuh Rule Level", value(e.rule_level, e.wazuh_rule_level));
    add("🎯 MITRE ATT&CK", e.attack);
    add("🔧 파일 변경 유형", value(e.fim_event, e.syscheck?.event));
  }

  if (rawTitle) add("📌 탐지 규칙", rawTitle, false);
  else if (detail) add("📌 탐지 유형", detail, false);

  add("📝 상세 탐지 사유",
    reason || `${detail || categoryTitle} 이벤트가 탐지되었습니다.`,
    false
  );

  add("🏷️ 담당자", e.student);
  add("🎫 이벤트 키", eventKey);
  add("🆔 이벤트 ID", value(e.event_id, e.id));

  if (present(e.hours)) add("⏱️ 리포트 기간", `${e.hours}시간`);

  const label = detail || categoryTitle;
  const embedTitle = `[${severity.toUpperCase()}] ${categoryTitle} | ${label}`;

  // Discord 전체 Embed 텍스트 6000자 제한
  let remaining = 5700 - safe(embedTitle, 256).length;
  const finalFields = [];

  for (const field of fields) {
    const name = field.name.slice(0, 256);
    const available = remaining - name.length;

    if (available <= 0) break;

    const val = field.value.slice(0, Math.min(1024, available));
    if (!val) continue;

    finalFields.push({ name, value: val, inline: field.inline });
    remaining -= name.length + val.length;
  }

  return {
    username: "Security Alert Bot",
    allowed_mentions: { parse: [] },
    embeds: [{
      title: safe(embedTitle, 256),
      description: safe(
        `${detail || categoryTitle} 관련 보안 이벤트가 탐지되었습니다.`,
        500
      ),
      color: severityColors[severity] ?? categoryColor,
      fields: finalFields,
      footer: {
        text: "Graylog · Wazuh · n8n | 대응 실행 여부 별도 확인"
      },
      timestamp: new Date().toISOString()
    }]
  };
})() }}

