// 거부 기준 숫자를 상수로 설정 (나중에 이 숫자만 바꾸면 기준이 변합니다)
const DENY_THRESHOLD = 10;
const MEDIUM_THRESHOLD = 7;

const results = [];

// Webhook으로 들어온 데이터를 하나씩 가져옵니다.
for (const item of $input.all()) {
  const student = item.json.body.student;
  const alerts = item.json.body.alerts || [];

  // 경보 목록을 한 건씩 펼쳐서 검사합니다.
  for (const alert of alerts) {
    const level = alert.level;
    const ip = alert.ip;
    const rule = alert.rule;

    let severity = "Low";
    let decision = "allow";

    // 레벨에 따른 판정 로직
    if (level >= DENY_THRESHOLD) {
      severity = "High";
      decision = "deny";
    } else if (level >= MEDIUM_THRESHOLD) {
      severity = "Medium";
      decision = "allow";
    }

    // 사람이 읽기 쉬운 판정 이유 문구 생성
    const reason = `level ${level} (rule ${rule}) → ${decision}`;

    // 결과를 목록에 추가
    results.push({
      json: {
        student: student,
        src_ip: ip,
        level: level,
        rule: rule,
        fail_count: 1,
        severity: severity,
        decision: decision,
        reason: reason
      }
    });
  }
}

return results;

const out=[];
for (const item of $input.all()){
  const b = (item.json ?? {}).body ?? item.json ?? {};
  const events = b.alerts ?? b.events ?? [b];

  for(const e of events){
    // IP가 없을 경우 임의의 샘플 IP 생성 또는 기존 값 유지
    const ip = e.src_ip ?? e.ip ?? `192.168.1.${Math.floor(Math.random() * 250) + 1}`;
    const title = e.rule ?? e.title ?? '집계 경보';
    const student = e.student ?? '이상용';

    // decision을 임의로 'allow' 또는 'deny' 중 하나로 생성 (deny 비중을 높이려면 조건 조정 가능)
    const decision = e.decision ?? (Math.random() < 0.7 ? 'deny' : 'allow');

    let kind = e.kind;
    if(!kind){ 
      kind = /상관|복합/.test(title) ? 'correlation' : (/스프레이|spray/i.test(title) ? 'spray' : 'aggregation'); 
    }

    const emoji = kind === 'correlation' ? '🚨' : '⚠️';
    const label = kind === 'correlation' ? '복합공격(네트워크+앱)' : (kind === 'spray' ? '계정 스프레이' : '집계 경보');

    out.push({
      json: { 
        src_ip: ip, 
        student: student,
        decision: decision,
        kind, 
        title,
        text: `${emoji} [${label}] 출발지 ${ip} — ${title} (student: ${student}, decision: ${decision})` 
      }
    });
  }
}
return out;

