    attack: 'T1070.004 File Deletion'
  }
};

const out = [];

for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const events = b.alerts ?? b.events ?? [b];

  if (!Array.isArray(events)) {
    throw new Error('alerts 또는 events는 배열이어야 합니다.');
  }

  for (const e of events) {
    if (!e || typeof e !== 'object') continue;

    const ruleId = String(
      e.rule_id ?? e.rule?.id ?? ''
    ).trim();

    if (!ruleId) {
      throw new Error('Wazuh rule_id가 없습니다.');
    }

    const m = MAP[ruleId] ?? {
      kind: '기타 Wazuh 경보',
      action: 'record',
      severity: 'Low',
      attack: '-'
    };

    const ip = String(
      e.srcip ?? e.src_ip ?? e.ip ?? ''
    ).trim();

    const agent = String(
      e.agent?.name ?? e.agent ?? 'unknown-agent'
    );

    const file = String(e.file ?? '');
    const user = String(e.user ?? e.username ?? '');
    const description = String(
      e.description ?? '상세 설명 없음'
    );

    const block =
      m.action === 'block' &&
      ip !== '' &&
      ip !== '0.0.0.0';

    const action = block ? 'block' : 'record';
    const key = block ? ip : `wazuh:${agent}`;

    const what = ip
      ? `출발지 ${ip}`
      : `파일 ${file || '-'} (${e.fim_event ?? '-'})`;

    out.push({
      json: {
        kind: m.kind,
        action,
        severity: m.severity,
        attack: m.attack,
        rule_id: ruleId,
        rule_level: e.rule_level ?? e.rule?.level ?? null,
        description,
        ip,
        src_ip: ip,
        user,
        file,
        agent,
        key,
        student: e.student ?? b.student ?? 'lsy',
        source: 'wazuh',
        reason: `[Wazuh ${ruleId}] ${description} - ${what} (${m.attack})`.slice(0, 200)
      }
    });
  }
}

return out;

// Graylog 집계 이벤트(브루트포스)에서 잠금 대상 생성
const out = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  const b = j.body ?? j;
  const events = b.alerts ?? b.events ?? (b.username ? [b] : []);
  for (const e of events) {
    const user = e.username ?? e.user;
    if (!user) continue;
    const cnt = e.count ?? e.fail_count ?? '?';
    out.push({ json: {
      username: user,
      reason: `브루트포스 자동 잠금: ${cnt}회 로그인 실패`,
      fail_count: Number(e.count ?? e.fail_count ?? 0),
      src_ip: e.src_ip ?? '0.0.0.0',
      student: e.student ?? b.student ?? 'lsy',
      severity: 'High', source: 'login-guard',
    }});
  }
}
return out;

// Graylog 집계 이벤트(다수 실패가 같은 src_ip) → IP 실차단 payload
const out = [];
for (const item of $input.all()) {
  const b = (item.json ?? {}).body ?? item.json ?? {};
  const events = b.alerts ?? b.events ?? (b.src_ip ? [b] : []);
  for (const e of events) {
    const ip = e.src_ip ?? e.ip;
    if (!ip || ip === '0.0.0.0') continue;         // 출발지 IP 없으면 차단 불가(스킵)
    const cnt = e.count ?? e.fail_count ?? '?';
    out.push({ json: {
      ip: ip, src_ip: ip,
      reason: `공격 출발지 자동 차단: ${cnt}회 로그인 실패(동일 IP)`,
      fail_count: Number(e.count ?? e.fail_count ?? 0),
      username: e.username ?? e.user ?? '', student: e.student ?? 'lsy',
      severity: 'High', source: 'ip-guard',
    }});
  }
}
return out;

