// EX 8종 + ED-WZ-02 이벤트 정규화
// Discord 메시지는 공통 '메시지' 노드에서 생성

const out = [];

const labels = {
  'EX-01': '포트 스캔',
  'EX-02': 'SYN Flood 의심',
  'EX-03': '저속 로그인 시도',
  'EX-04': '심야 로그인 성공',
  'EX-05': 'SQL Injection 의심',
  'EX-06': '내부 비인가 접근',
  'EX-07': '로그 변조·삭제',
  'EX-08': 'Nikto 스캐너 식별'
};

const highRules = [
  'EX-02',
  'EX-05',
  'EX-06',
  'EX-07'
];

for (const item of $input.all()) {
  const b = item.json?.body ?? item.json ?? {};

  const events = Array.isArray(b.alerts)
    ? b.alerts
    : Array.isArray(b.events)
      ? b.events
      : [b];

  for (const e of events) {
    if (!e || typeof e !== 'object') continue;

    const title = String(
      e.event_definition ??
      e.rule ??
      b.event_definition ??
      'EX 보안 탐지 이벤트'
    );

    const exId = (
      title.match(/EX-0[1-8]/i) ?? []
    )[0]?.toUpperCase() ?? '';

    const isWazuh =
      /ED-WZ-02|Linux 호스트 보안/i.test(title) ||
      e.source === 'wazuh' ||
      e.wazuh_rule_id != null;

    const label = isWazuh
      ? 'Wazuh Linux 호스트 보안'
      : labels[exId] ?? '공방전 시나리오';

    const groupKey = e.group_key ??
      e.event_key ??
      b.group_key ??
      b.event_key ??
      '';

    const rawPriority = Number(
      e.severity ?? b.severity
    );

    const severity =
      highRules.includes(exId) ||
      rawPriority >= 3
        ? 'High'
        : 'Medium';

    const ruleId =
      e.rule_id ??
      e.wazuh_rule_id ??
      b.rule_id ??
      b.wazuh_rule_id;

    out.push({
      json: {
        source: isWazuh ? 'wazuh' : 'scenario-alert',
        kind: isWazuh ? 'wazuh' : 'scenario-alert',

        event_definition: title,
        rule: title,
        scenario_id: exId,
        scenario_name: label,

        severity,
        decision: 'alert',

        reason: `${label} 관련 탐지 이벤트 발생`,

        group_key: groupKey,
        event_key: groupKey,
        event_id: e.event_id ?? b.event_id,

        src_ip: e.src_ip ?? e.ip ?? b.src_ip,
        username: e.username ?? b.username,
        agent: e.agent ?? b.agent,
        file: e.file ?? b.file,
        rule_id: ruleId,
        rule_level: e.rule_level ?? b.rule_level,
        fim_event: e.fim_event ?? b.fim_event,

        count: e.count ?? b.count,
        student: e.student ?? b.student ?? 'security-team'
      }
    });
  }
}

return out;
